def has_dup(nums):
    seen = set()
    for x in nums:
        if x in seen:
            return True
        seen.add(x)
    return False

def count_doublings(n):
    i, steps = 1, 0
    while i < n:
        i *= 2
        steps += 1
    return steps

def all_pairs(a):
    res = []
    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            res.append((a[i], a[j]))
    return res

def concat(words):
    s = ""
    for w in words:
        s += w
    return s

def halving_work(n):
    total = 0
    while n > 0:
        for _ in range(n):
            total += 1
        n //= 2
    return total

def merge(nums1, m, nums2, n):
    i, j, k = m - 1, n - 1, m + n - 1
    while j > 0:
        if i >= 0 and nums1[i] > nums2[j]:
            nums1[k] = nums1[i]
            i -= 1
        else:
            nums1[k] = nums2[j]
            j -= 1
        k -= 1

def longest_common_prefix(strs):
    prefix = strs[0]
    for s in strs[1:]:
        while prefix not in s:
            prefix = prefix[:-1]
    return prefix

def plus_one(d):
    for i in range(len(d) - 1, -1, -1):
        if d[i] < 9:
            d[i] += 1
            return d
        d[i] = 0
    return d
